  ],
  "claims": [
    {
      "claim": "The only cirrhosis-matched absolute oral bioavailability record is meptazinol 27.9 ± 5.3% after a 200 mg p.o. dose in cirrhotic patients (n=8), which is above the F ≥ 20% threshold; L2 repeats confirm the same value.",
      "card_ids": ["C05", "C19", "C23"]
    },
    {
      "claim": "Direct human absolute oral bioavailability measurements in other contexts are above threshold: cilomilast 96% (103% tablet), vernakalant 71 ± 21% and 58 ± 19%, and imipramine 43.6 ± 4.6%.",
      "card_ids": ["C08", "C20", "C13", "C15", "C06", "C14", "C16"]
    },
    {
      "claim": "L6 verapamil hepatic-clearance records show high intrinsic clearance in human liver microsomes and hepatocytes (e.g., CLint 34–228 µL/min/mg and scaled hepatic clearance 16.5 mL/min/kg), indicating extensive first-pass metabolism for verapamil; however, these are not query measurements and do not provide a threshold-specific F for the query, and cirrhosis attenuates first-pass loss.",
      "card_ids": ["C61", "C62", "C63", "C64", "C65", "C66", "C67", "C68", "C69", "C70", "C71", "C72"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C61", "C62", "C63", "C64", "C65", "C66", "C67", "C68", "C69", "C70", "C71", "C72"]
    }
  ],
  "evidence_gaps": [
    "No query-specific absolute oral bioavailability or matched oral-versus-IV exposure data are available.",
    "No query-specific permeability, solubility, efflux, or hepatic-clearance measurements exist; L6 records are for verapamil, not the query.",
    "No cirrhosis-specific pharmacokinetic data exist for the query or a close structural analog; the only cirrhosis-matched F record is meptazinol, a different scaffold.",
    "Verapamil's own absolute F is not reported in the cards, so the L6 clearance values cannot be converted into a threshold-specific F for the query.",
    "The physicochemical prior is mixed (high MW/TPSA/charge and low logD versus no HBD and moderate logP) and cannot by itself establish F < 20%."
  ],
  "decision_summary": "Predicted high because all threshold-relevant absolute F records, including the only cirrhosis-matched F (meptazinol 27.9 ± 5.3%), are at or above the 20% threshold; L6 verapamil hepatic-clearance evidence is mechanistically relevant and weakens confidence but does not affirm F < 20% for the query, especially under cirrhosis where first-pass metabolism is attenuated. Confidence is low and the prior decision is weakened, not flipped."
}

